import { test } from "node:test";
import assert from "node:assert/strict";
import { allocate } from "../src/billing/allocate.ts";
import { chargeBackInvoice } from "../src/billing/splitInvoice.ts";
import { prorate } from "../src/billing/proration.ts";
import { formatCents, parseDollars } from "../src/billing/money.ts";

const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);

test("splitting $1.00 three ways gives 34, 33, 33", () => {
    const shares = allocate(100, [1, 1, 1]);
    console.log("allocate(100, [1, 1, 1]) =", shares);
    assert.deepEqual(shares, [34, 33, 33]);
});

test("shares always add up to the amount", () => {
    const cases: [number, number[]][] = [
        [2, [1, 1, 1]],
        [10, [1, 1, 1, 1]],
        [99999, [3, 7, 11, 13]],
        [1, [5, 5]],
        [12345, [0.1, 0.2, 0.3]],
    ];
    for (const [amount, weights] of cases) {
        assert.equal(sum(allocate(amount, weights)), amount, `allocate(${amount}, [${weights}])`);
    }
});

test("proportions are respected when they divide evenly, and bad input is rejected", () => {
    assert.deepEqual(allocate(1000, [1, 3]), [250, 750]);
    assert.deepEqual(allocate(5, [0, 1]), [0, 5]);
    assert.throws(() => allocate(10.5, [1]));
    assert.throws(() => allocate(10, [0, 0]));
    assert.throws(() => allocate(10, []));
});

test("an invoice charged back to three equal teams balances", () => {
    const entries = chargeBackInvoice("INV-7", 10000, [
        { account: "expense:search", seats: 4 },
        { account: "expense:ads", seats: 4 },
        { account: "expense:infra", seats: 4 },
    ]);
    assert.equal(sum(entries.map((e) => e.debitCents)), 10000);
});

test("upgrading mid-month credits the unused days and charges the rest of the new plan", () => {
    // $30 -> $90 plan, 10 of 30 days used
    assert.deepEqual(prorate({ oldPriceCents: 3000, newPriceCents: 9000, daysInPeriod: 30, daysUsed: 10 }), {
        creditCents: 2000, chargeCents: 6000, netCents: 4000,
    });
    assert.deepEqual(prorate({ oldPriceCents: 3000, newPriceCents: 9000, daysInPeriod: 30, daysUsed: 30 }), {
        creditCents: 0, chargeCents: 0, netCents: 0,
    });
    assert.throws(() => prorate({ oldPriceCents: 3000, newPriceCents: 9000, daysInPeriod: 30, daysUsed: 31 }));
});

test("used and unused parts of a price never gain or lose a cent", () => {
    // $29.99 plan switched exactly half way through a 30-day month: 14.995 each way
    const lines = prorate({ oldPriceCents: 2999, newPriceCents: 4999, daysInPeriod: 30, daysUsed: 15 });
    console.log("half-month proration:", lines);
    assert.equal(allocate(2999, [15, 15])[0] + lines.creditCents, 2999);
    assert.equal(allocate(4999, [15, 15])[0] + lines.chargeCents, 4999);
    assert.deepEqual(lines, { creditCents: 1499, chargeCents: 2499, netCents: 1000 });
});

test("amounts are formatted and parsed without floating point", () => {
    assert.equal(formatCents(123456), "$1,234.56");
    assert.equal(formatCents(-5), "-$0.05");
    assert.equal(formatCents(100000000, "EUR"), "EUR 1,000,000.00");
    assert.equal(parseDollars("$1,234.5"), 123450);
    assert.equal(parseDollars("0.29"), 29);
    assert.throws(() => parseDollars("1.234"));
});
